#!/usr/bin/env bash
set -euo pipefail
clear
echo "==============================================================="
echo " PINCABOS — INSTALL MEDIA RECORDER WEB V1"
echo "==============================================================="
STAMP="$(date +%Y%m%d-%H%M%S)"
WEB="/opt/pincabos/web"
TOOLS="$WEB/tools.py"
REC="$WEB/recorder.py"
BACKUP="/opt/pincabos/backups/media-recorder-web-$STAMP"
STATE="/var/lib/pincabos/media-recorder"
fail(){ echo; echo "NOGO [X] $*"; exit 1; }
echo; echo "=== 1. AUDIT ==="
[ -f "$TOOLS" ] || fail "tools.py absent"
[ -f "$REC" ] || fail "recorder.py absent"
python3 -m py_compile "$TOOLS" "$REC" || fail "Python actuel invalide"
echo "GO [OK] tools.py"; echo "GO [OK] recorder.py"
echo; echo "=== 2. BACKUP ==="
mkdir -p "$BACKUP"
cp -a "$TOOLS" "$BACKUP/tools.py"
cp -a "$REC" "$BACKUP/recorder.py"
[ -f "$WEB/pincabos_media_recorder.py" ] && cp -a "$WEB/pincabos_media_recorder.py" "$BACKUP/" || true
[ -f "$WEB/pincabos_media_recorder_worker.py" ] && cp -a "$WEB/pincabos_media_recorder_worker.py" "$BACKUP/" || true
[ -f /etc/systemd/system/pincabos-media-recorder-worker.service ] && cp -a /etc/systemd/system/pincabos-media-recorder-worker.service "$BACKUP/" || true
echo "GO [OK] Backup : $BACKUP"
echo; echo "=== 3. INSTALLATION FICHIERS ==="
printf '%s' '' | base64 -d > '/opt/pincabos/web/pincabos_media_recorder.py'
chmod 644 '/opt/pincabos/web/pincabos_media_recorder.py'
chown root:pinball '/opt/pincabos/web/pincabos_media_recorder.py'
printf '%s' '' | base64 -d > '/opt/pincabos/web/pincabos_media_recorder_worker.py'
chmod 755 '/opt/pincabos/web/pincabos_media_recorder_worker.py'
chown root:pinball '/opt/pincabos/web/pincabos_media_recorder_worker.py'
printf '%s' '' | base64 -d > '/etc/systemd/system/pincabos-media-recorder-worker.service'
chmod 644 '/etc/systemd/system/pincabos-media-recorder-worker.service'
chown root:root '/etc/systemd/system/pincabos-media-recorder-worker.service'
printf '%s' '' | base64 -d > '/tmp/pincabos-media-recorder-patch-tools.py'
chmod 700 '/tmp/pincabos-media-recorder-patch-tools.py'
chown root:root '/tmp/pincabos-media-recorder-patch-tools.py'
echo "GO [OK] Module + worker + service"
echo; echo "=== 4. PATCH OUTILS ==="
python3 /tmp/pincabos-media-recorder-patch-tools.py "$TOOLS" || { cp -a "$BACKUP/tools.py" "$TOOLS"; fail "Patch tools.py échoué"; }
rm -f /tmp/pincabos-media-recorder-patch-tools.py
echo; echo "=== 5. ETAT RUNTIME ==="
install -d -o root -g pinball -m 0775 "$STATE" "$STATE/logs" "$STATE/history"
if [ ! -f "$STATE/status.json" ]; then printf '%s\n' '{"state":"idle","index":0,"total":0,"message":"Worker prêt."}' > "$STATE/status.json"; fi
chown root:pinball "$STATE/status.json"; chmod 0664 "$STATE/status.json"
echo "GO [OK] $STATE"
echo; echo "=== 6. VALIDATION PYTHON ==="
python3 -m py_compile "$TOOLS" "$REC" "$WEB/pincabos_media_recorder.py" "$WEB/pincabos_media_recorder_worker.py" || { cp -a "$BACKUP/tools.py" "$TOOLS"; fail "Erreur Python"; }
echo "GO [OK] Syntaxe Python"
echo; echo "=== 7. SYSTEMD WORKER ==="
systemctl daemon-reload
systemctl enable --now pincabos-media-recorder-worker.service
sleep 1
systemctl is-active --quiet pincabos-media-recorder-worker.service || { systemctl status pincabos-media-recorder-worker.service --no-pager -l || true; fail "Worker non actif"; }
echo "GO [OK] Worker actif"
echo; echo "=== 8. RESTART WEBAPP ==="
systemctl restart pincabos-webapp.service
sleep 2
systemctl is-active --quiet pincabos-webapp.service || { systemctl status pincabos-webapp.service --no-pager -l || true; fail "WebApp non actif"; }
echo "GO [OK] WebApp actif"
echo; echo "=== 9. VALIDATION ROUTES ==="
python3 - <<'PY_CHECK'
import urllib.request
for url in ('http://127.0.0.1/tools/media-recorder','http://127.0.0.1/api/media-recorder/status'):
    with urllib.request.urlopen(url, timeout=8) as r: print(f"GO [OK] {url} -> HTTP {r.status}")
PY_CHECK
echo; echo "=== 10. RESUME ==="
echo "Worker : $(systemctl is-active pincabos-media-recorder-worker.service || true)"
echo "WebApp : $(systemctl is-active pincabos-webapp.service || true)"
echo "Page    : http://$(hostname -I | awk '{print $1}')/tools/media-recorder"
echo "Backup  : $BACKUP"
echo; echo "==============================================================="
echo " GO [OK] MEDIA RECORDER WEB V1 INSTALLE"
echo "==============================================================="
